BOOL KARPAWriteRuntimeDiffFromFiles(NSString *beforePath,NSString *afterPath,NSString *outputPath,NSError **error){NSData *a=[NSData dataWithContentsOfFile:beforePath],*b=[NSData dataWithContentsOfFile:afterPath];if(!a||!b){if(error)*error=[NSError errorWithDomain:@"com.example.authorized.KARPA" code:10 userInfo:@{NSLocalizedDescriptionKey:@"Unable to read one or both snapshot files"}];return NO;}NSError *x=nil;NSDictionary *ba=[NSJSONSerialization JSONObjectWithData:a options:0 error:&x],*af=[NSJSONSerialization JSONObjectWithData:b options:0 error:&x];if(!ba||![af isKindOfClass:NSDictionary.class]){if(error)*error=x;return NO;}NSData *d=[NSJSONSerialization dataWithJSONObject:KARPAComputeRuntimeDiff(ba,af) options:NSJSONWritingPrettyPrinted error:&x];if(!d||![d writeToFile:outputPath options:NSDataWritingAtomic error:&x]){if(error)*error=x;return NO;}return YES;}
